extends RigidBody3D


const ACCEL: float = 5.0
const DEACCEL: float = 20.0
const MAX_SPEED: float = 2.0
const ROT_SPEED: float = 1.0

var prev_advance: bool = false
var dying: bool = false
var rot_dir: float = 4.0

@onready var gravity := Vector3(
		ProjectSettings.get_setting("physics/3d/default_gravity") * ProjectSettings.get_setting("physics/3d/default_gravity_vector")
)

@onready var _animation_player := $Enemy/AnimationPlayer as AnimationPlayer
@onready var _ray_floor := $Enemy/Skeleton/RayFloor as RayCast3D
@onready var _ray_wall := $Enemy/Skeleton/RayWall as RayCast3D


func _integrate_forces(state: PhysicsDirectBodyState3D) -> void:
	var delta := state.get_step()
	var lin_velocity := state.get_linear_velocity()
	var grav := state.get_total_gravity()
	# get_total_gravity returns zero for the first few frames, leading to errors.
	if grav.is_zero_approx():
		grav = gravity

	lin_velocity += grav * delta # Apply gravity.
	var up := -grav.normalized()

	if dying:
		state.set_linear_velocity(lin_velocity)
		return

	for i in state.get_contact_count():
		var contact_collider := state.get_contact_collider_object(i)
		var contact_normal := state.get_contact_local_normal(i)

		if is_instance_valid(contact_collider):
			if contact_collider is Bullet and contact_collider.enabled:
				dying = true
				axis_lock_angular_x = false
				axis_lock_angular_y = false
				axis_lock_angular_z = false
				collision_layer = 0
				state.set_angular_velocity(-contact_normal.cross(up).normalized() * 33.0)
				_animation_player.play(&"impact")
				_animation_player.queue(&"extra/explode")
				contact_collider.enabled = false
				$SoundWalkLoop.stop()
				$SoundHit.play()
				return

	var advance: bool = _ray_floor.is_colliding() and not _ray_wall.is_colliding()

	var dir: Vector3 = ($Enemy/Skeleton as Node3D).get_transform().basis.z.normalized()
	var deaccel_dir: Vector3 = dir

	if advance:
		if dir.dot(lin_velocity) < MAX_SPEED:
			lin_velocity += dir * ACCEL * delta
		deaccel_dir = dir.cross(gravity).normalized()
	else:
		if prev_advance:
			rot_dir = 1

		dir = Basis(up, rot_dir * ROT_SPEED * (delta)) * dir
		$Enemy/Skeleton.set_transform(Transform3D().looking_at(-dir, up))

	var dspeed: float = deaccel_dir.dot(lin_velocity)
	dspeed -= DEACCEL * delta
	if dspeed < 0:
		dspeed = 0

	lin_velocity = lin_velocity - deaccel_dir * deaccel_dir.dot(lin_velocity) \
			+ deaccel_dir * dspeed

	state.set_linear_velocity(lin_velocity)
	prev_advance = advance


func _die() -> void:
	queue_free()

extends Camera3D


const MAX_HEIGHT = 2.0
const MIN_HEIGHT = 0.0

var collision_exception: Array[RID] = []

@export var min_distance: float = 0.5
@export var max_distance: float = 3.5
@export var angle_v_adjust: float = 0.0
@export var autoturn_ray_aperture: float = 25.0
@export var autoturn_speed: float = 50.0


func _ready() -> void:
	# Find collision exceptions for ray.
	# This is done to prevent the player and enemies from colliding
	# with the camera.
	var node: Node = self
	while is_instance_valid(node):
		if node is RigidBody3D or node is CharacterBody3D:
			collision_exception.append(node.get_rid())
			break
		else:
			node = node.get_parent()

	# This detaches the camera transform from the parent spatial node.
	set_as_top_level(true)


func _physics_process(delta: float) -> void:
	var target := (get_parent() as Node3D).get_global_transform().origin
	var pos := get_global_transform().origin

	var difference := pos - target

	# Regular delta follow.

	# Check ranges.
	if difference.length() < min_distance:
		difference = difference.normalized() * min_distance
	elif  difference.length() > max_distance:
		difference = difference.normalized() * max_distance

	# Check upper and lower height.
	difference.y = clamp(difference.y, MIN_HEIGHT, MAX_HEIGHT)

	# Check autoturn.
	var ds := PhysicsServer3D.space_get_direct_state(get_world_3d().get_space())

	var col_left := ds.intersect_ray(PhysicsRayQueryParameters3D.create(
			target,
			target + Basis(Vector3.UP, deg_to_rad(autoturn_ray_aperture)) * (difference),
			0xffffffff,
			collision_exception
		))
	var col := ds.intersect_ray(PhysicsRayQueryParameters3D.create(
			target,
			target + difference,
			0xffffffff,
			collision_exception
		))
	var col_right := ds.intersect_ray(PhysicsRayQueryParameters3D.create(
			target,
			target + Basis(Vector3.UP, deg_to_rad(-autoturn_ray_aperture)) * (difference),
			0xffffffff,
			collision_exception
		))

	if not col.is_empty():
		# If main ray was occluded, get camera closer, this is the worst case scenario.
		difference = col.position - target
	elif not col_left.is_empty() and col_right.is_empty():
		# If only left ray is occluded, turn the camera around to the right.
		difference = Basis(Vector3.UP, deg_to_rad(-delta * (autoturn_speed))) * difference
	elif col_left.is_empty() and not col_right.is_empty():
		# If only right ray is occluded, turn the camera around to the left.
		difference = Basis(Vector3.UP, deg_to_rad(delta * autoturn_speed)) * difference
	# Do nothing otherwise, left and right are occluded but center is not, so do not autoturn.

	# Apply lookat.
	if difference.is_zero_approx():
		difference = (pos - target).normalized() * 0.0001

	pos = target + difference

	look_at_from_position(pos, target, Vector3.UP)

	# Turn a little up or down.
	transform.basis = Basis(transform.basis[0], deg_to_rad(angle_v_adjust)) * transform.basis

class_name Player
extends CharacterBody3D

enum _Anim {
	FLOOR,
	AIR,
}

const SHOOT_TIME: float = 1.5
const SHOOT_SCALE: float = 2.0
const CHAR_SCALE := Vector3(0.3, 0.3, 0.3)
const MAX_SPEED: float = 6.0
const TURN_SPEED: float = 40.0
const JUMP_VELOCITY: float = 12.5
const BULLET_SPEED: float = 20.0
const AIR_IDLE_DEACCEL: bool = false
const ACCEL: float = 14.0
const DEACCEL: float = 14.0
const AIR_ACCEL_FACTOR: float = 0.5
const SHARP_TURN_THRESHOLD: float = deg_to_rad(140.0)

var movement_dir := Vector3()
var jumping: bool = false
var prev_shoot: bool = false
var shoot_blend: float = 0.0

# Number of coins collected.
var coins: int = 0

@onready var initial_position := position
@onready var gravity: Vector3 = ProjectSettings.get_setting("physics/3d/default_gravity") * \
		ProjectSettings.get_setting("physics/3d/default_gravity_vector")

@onready var _camera := $Target/Camera3D as Camera3D
@onready var _animation_tree := $AnimationTree as AnimationTree


func _physics_process(delta: float) -> void:
	if Input.is_action_pressed(&"reset_position") or global_position.y < -12:
		# Player hit the reset button or fell off the map.
		position = initial_position
		velocity = Vector3.ZERO
		# We teleported the player on the lines above. Reset interpolation
		# to prevent it from interpolating from the old player position
		# to the new position.
		reset_physics_interpolation()

	# Update coin count and its "parallax" copies.
	# This gives text a pseudo-3D appearance while still using Label3D instead of the more limited TextMesh.
	%CoinCount.text = str(coins)
	%CoinCount.get_node(^"Parallax").text = str(coins)
	%CoinCount.get_node(^"Parallax2").text = str(coins)
	%CoinCount.get_node(^"Parallax3").text = str(coins)
	%CoinCount.get_node(^"Parallax4").text = str(coins)

	velocity += gravity * delta

	var anim := _Anim.FLOOR

	var vertical_velocity := velocity.y
	var horizontal_velocity := Vector3(velocity.x, 0, velocity.z)

	var horizontal_direction := horizontal_velocity.normalized()
	var horizontal_speed := horizontal_velocity.length()

	# Player input.
	var cam_basis := _camera.get_global_transform().basis
	var movement_vec2 := Input.get_vector(&"move_left", &"move_right", &"move_forward", &"move_back")
	var movement_direction := cam_basis * Vector3(movement_vec2.x, 0, movement_vec2.y)
	movement_direction.y = 0
	movement_direction = movement_direction.normalized()

	var jump_attempt := Input.is_action_pressed(&"jump")

	if is_on_floor():
		var sharp_turn := horizontal_speed > 0.1 and \
				acos(movement_direction.dot(horizontal_direction)) > SHARP_TURN_THRESHOLD

		if movement_direction.length() > 0.1 and not sharp_turn:
			if horizontal_speed > 0.001:
				horizontal_direction = adjust_facing(
						horizontal_direction,
						movement_direction,
						delta,
						1.0 / horizontal_speed * TURN_SPEED,
						Vector3.UP
					)
			else:
				horizontal_direction = movement_direction

			if horizontal_speed < MAX_SPEED:
				horizontal_speed += ACCEL * delta
		else:
			horizontal_speed -= DEACCEL * delta
			if horizontal_speed < 0:
				horizontal_speed = 0

		horizontal_velocity = horizontal_direction * horizontal_speed

		var mesh_xform := ($Player/Skeleton as Node3D).get_transform()
		var facing_mesh := -mesh_xform.basis[0].normalized()
		facing_mesh = (facing_mesh - Vector3.UP * facing_mesh.dot(Vector3.UP)).normalized()

		if horizontal_speed > 0:
			facing_mesh = adjust_facing(
					facing_mesh,
					movement_direction,
					delta,
					1.0 / horizontal_speed * TURN_SPEED,
					Vector3.UP
				)
		var m3 := Basis(
				-facing_mesh,
				Vector3.UP,
				-facing_mesh.cross(Vector3.UP).normalized()
			).scaled(CHAR_SCALE)

		$Player/Skeleton.set_transform(Transform3D(m3, mesh_xform.origin))

		if not jumping and jump_attempt:
			vertical_velocity = JUMP_VELOCITY
			jumping = true
			$SoundJump.play()

	else:
		anim = _Anim.AIR

		if movement_direction.length() > 0.1:
			horizontal_velocity += movement_direction * (ACCEL * AIR_ACCEL_FACTOR * delta)
			if horizontal_velocity.length() > MAX_SPEED:
				horizontal_velocity = horizontal_velocity.normalized() * MAX_SPEED
		elif AIR_IDLE_DEACCEL:
			horizontal_speed = horizontal_speed - (DEACCEL * AIR_ACCEL_FACTOR * delta)
			if horizontal_speed < 0:
				horizontal_speed = 0
			horizontal_velocity = horizontal_direction * horizontal_speed

		if Input.is_action_just_released(&"jump") and velocity.y > 0.0:
			# Reduce jump height if releasing the jump key before reaching the apex.
			vertical_velocity *= 0.7

	if jumping and vertical_velocity < 0:
		jumping = false

	velocity = horizontal_velocity + Vector3.UP * vertical_velocity

	if is_on_floor():
		movement_dir = velocity

	move_and_slide()

	if shoot_blend > 0:
		shoot_blend *= 0.97
		if (shoot_blend < 0):
			shoot_blend = 0
	var shoot_attempt := Input.is_action_pressed(&"shoot")
	if shoot_attempt and not prev_shoot:
		shoot_blend = SHOOT_TIME
		var bullet := preload("res://player/bullet/bullet.tscn").instantiate() as Bullet
		bullet.set_transform($Player/Skeleton/Bullet.get_global_transform().orthonormalized())
		get_parent().add_child(bullet)
		bullet.set_linear_velocity(
				$Player/Skeleton/Bullet.get_global_transform().basis[2].normalized() * BULLET_SPEED
			)
		bullet.add_collision_exception_with(self)
		$SoundShoot.play()

	prev_shoot = shoot_attempt

	if is_on_floor():
		# How much the player should be blending between the "idle" and "walk/run" animations.
		_animation_tree[&"parameters/run/blend_amount"] = horizontal_speed / MAX_SPEED

		# How much the player should be running (as opposed to walking). 0.0 = fully walking, 1.0 = fully running.
		_animation_tree[&"parameters/speed/blend_amount"] = minf(1.0, horizontal_speed / (MAX_SPEED * 0.5))

	_animation_tree[&"parameters/state/blend_amount"] = anim
	_animation_tree[&"parameters/air_dir/blend_amount"] = clampf(-velocity.y / 4 + 0.5, 0, 1)
	_animation_tree[&"parameters/gun/blend_amount"] = minf(shoot_blend, 1.0)


func adjust_facing(facing: Vector3, target: Vector3, step: float, adjust_rate: float, \
		current_gn: Vector3) -> Vector3:
	var normal := target
	var t := normal.cross(current_gn).normalized()

	var x := normal.dot(facing)
	var y := t.dot(facing)

	var ang := atan2(y,x)

	if absf(ang) < 0.001:
		return facing

	var s := signf(ang)
	ang = ang * s
	var turn := ang * adjust_rate * step
	var a: float
	if ang < turn:
		a = ang
	else:
		a = turn
	ang = (ang - a) * s

	return (normal * cos(ang) + t * sin(ang)) * facing.length()

class_name VirtualJoystick
extends Control

## A simple virtual joystick for touchscreens, with useful options.
## Github: https://github.com/MarcoFazioRandom/Virtual-Joystick-Godot

# EXPORTED VARIABLES

## The color of the button when the joystick is pressed.
@export var pressed_color := Color.GRAY

## If the input is inside this range, the output is zero.
@export_range(0, 200, 1) var deadzone_size: float = 10.0

## The max distance the tip can reach.
@export_range(0, 500, 1) var clampzone_size: float = 75.0

enum Joystick_mode {
	FIXED, ## The joystick doesn't move.
	DYNAMIC, ## Every time the joystick area is pressed, the joystick position is set on the touched position.
	FOLLOWING, ## When the finger moves outside the joystick area, the joystick will follow it.
}

## If the joystick stays in the same position or appears on the touched position when touch is started.
@export var joystick_mode := Joystick_mode.FIXED

enum Visibility_mode {
	ALWAYS, ## Always visible.
	TOUCHSCREEN_ONLY, ## Visible on touch screens only.
	WHEN_TOUCHED, ## Visible only when touched.
}

## If the joystick is always visible, or is shown only if there is a touchscreen.
@export var visibility_mode := Visibility_mode.ALWAYS

## If true, the joystick uses Input Actions. (Project -> Project Settings -> Input Map)
@export var use_input_actions: bool = true

@export var action_left: String = "move_left"
@export var action_right: String = "move_right"
@export var action_up: String = "move_forward"
@export var action_down: String = "move_back"

# PUBLIC VARIABLES

## If the joystick is receiving inputs.
var is_pressed: bool = false

# The joystick output.
var output := Vector2.ZERO

# PRIVATE VARIABLES

var _touch_index: int = -1

@onready var _base: TextureRect = $Base
@onready var _tip: TextureRect = $Base/Tip

@onready var _base_default_position: Vector2 = _base.position
@onready var _tip_default_position: Vector2 = _tip.position

@onready var _default_color : Color = _tip.modulate

# FUNCTIONS

func _ready() -> void:
	if not DisplayServer.is_touchscreen_available():
		hide()

	if visibility_mode == Visibility_mode.WHEN_TOUCHED:
		hide()


func _input(input_event: InputEvent) -> void:
	if input_event is InputEventScreenTouch:
		if input_event.pressed:
			if _is_point_inside_joystick_area(input_event.position) and _touch_index == -1:
				if joystick_mode == Joystick_mode.DYNAMIC or joystick_mode == Joystick_mode.FOLLOWING or (
						joystick_mode == Joystick_mode.FIXED and _is_point_inside_base(input_event.position)):
					if joystick_mode == Joystick_mode.DYNAMIC or joystick_mode == Joystick_mode.FOLLOWING:
						_move_base(input_event.position)
					if visibility_mode == Visibility_mode.WHEN_TOUCHED:
						show()
					_touch_index = input_event.index
					_tip.modulate = pressed_color
					_update_joystick(input_event.position)
					get_viewport().set_input_as_handled()
		elif input_event.index == _touch_index:
			_reset()
			if visibility_mode == Visibility_mode.WHEN_TOUCHED:
				hide()
			get_viewport().set_input_as_handled()
	elif input_event is InputEventScreenDrag:
		if input_event.index == _touch_index:
			_update_joystick(input_event.position)
			get_viewport().set_input_as_handled()


func _move_base(new_position: Vector2) -> void:
	_base.global_position = new_position - _base.pivot_offset * get_global_transform_with_canvas().get_scale()


func _move_tip(new_position: Vector2) -> void:
	_tip.global_position = new_position - _tip.pivot_offset * _base.get_global_transform_with_canvas().get_scale()


func _is_point_inside_joystick_area(point: Vector2) -> bool:
	var x: bool = point.x >= global_position.x and point.x <= global_position.x + (size.x * get_global_transform_with_canvas().get_scale().x)
	var y: bool = point.y >= global_position.y and point.y <= global_position.y + (size.y * get_global_transform_with_canvas().get_scale().y)
	return x and y


func _get_base_radius() -> Vector2:
	return _base.size * _base.get_global_transform_with_canvas().get_scale() / 2.0


func _is_point_inside_base(point: Vector2) -> bool:
	var base_radius: Vector2 = _get_base_radius()
	var center: Vector2 = _base.global_position + base_radius
	var vector: Vector2 = point - center
	return vector.length_squared() <= base_radius.x * base_radius.x


func _update_joystick(touch_position: Vector2) -> void:
	var base_radius: Vector2 = _get_base_radius()
	var center: Vector2 = _base.global_position + base_radius
	var vector: Vector2 = touch_position - center
	vector = vector.limit_length(clampzone_size)

	if joystick_mode == Joystick_mode.FOLLOWING and touch_position.distance_to(center) > clampzone_size:
		_move_base(touch_position - vector)

	_move_tip(center + vector)

	if vector.length_squared() > deadzone_size * deadzone_size:
		is_pressed = true
		output = (vector - (vector.normalized() * deadzone_size)) / (clampzone_size - deadzone_size)
	else:
		is_pressed = false
		output = Vector2.ZERO

	if use_input_actions:
		# Release actions.
		if output.x >= 0.0 and Input.is_action_pressed(action_left):
			Input.action_release(action_left)
		if output.x <= 0.0 and Input.is_action_pressed(action_right):
			Input.action_release(action_right)
		if output.y >= 0.0 and Input.is_action_pressed(action_up):
			Input.action_release(action_up)
		if output.y <= 0.0 and Input.is_action_pressed(action_down):
			Input.action_release(action_down)

		# Press actions.
		if output.x < 0.0:
			Input.action_press(action_left, -output.x)
		if output.x > 0.0:
			Input.action_press(action_right, output.x)
		if output.y < 0.0:
			Input.action_press(action_up, -output.y)
		if output.y > 0.0:
			Input.action_press(action_down, output.y)


func _reset() -> void:
	is_pressed = false
	output = Vector2.ZERO
	_touch_index = -1
	_tip.modulate = _default_color
	_base.position = _base_default_position
	_tip.position = _tip_default_position
	# Release actions.
	if use_input_actions:
		for action:String in [action_left, action_right, action_down, action_up]:
			if Input.is_action_pressed(action):
				Input.action_release(action)

extends WorldEnvironment


const ROT_SPEED = 0.003
const ZOOM_SPEED = 0.125
const MAIN_BUTTONS = MOUSE_BUTTON_MASK_LEFT | MOUSE_BUTTON_MASK_RIGHT | MOUSE_BUTTON_MASK_MIDDLE

var tester_index: int = 0
var rot_x: float = deg_to_rad(-22.5)  # This must be kept in sync with RotationX.
var rot_y: float = deg_to_rad(90)  # This must be kept in sync with CameraHolder.
var zoom: float = 2.5
var is_compatibility: bool = false

@onready var testers: Node3D = $Testers
@onready var camera_holder: Node3D = $CameraHolder  # Has a position and rotates on Y.
@onready var rotation_x: Node3D = $CameraHolder/RotationX
@onready var camera: Camera3D = $CameraHolder/RotationX/Camera3D


func _ready() -> void:
	if RenderingServer.get_current_rendering_method() == "gl_compatibility":
		# Use PCF13 shadow filtering to improve quality (Medium maps to PCF5 instead).
		RenderingServer.directional_soft_shadow_filter_set_quality(RenderingServer.SHADOW_QUALITY_SOFT_HIGH)

		# Darken the light's energy to compensate for sRGB blending (without affecting sky rendering).
		$DirectionalLight3D.sky_mode = DirectionalLight3D.SKY_MODE_SKY_ONLY
		var new_light: DirectionalLight3D = $DirectionalLight3D.duplicate()
		new_light.light_energy = 0.25
		new_light.sky_mode = DirectionalLight3D.SKY_MODE_LIGHT_ONLY
		add_child(new_light)

	camera_holder.transform.basis = Basis.from_euler(Vector3(0, rot_y, 0))
	rotation_x.transform.basis = Basis.from_euler(Vector3(rot_x, 0, 0))
	update_gui()


func _unhandled_input(input_event: InputEvent) -> void:
	if input_event.is_action_pressed(&"ui_left"):
		_on_previous_pressed()
	if input_event.is_action_pressed(&"ui_right"):
		_on_next_pressed()

	if input_event is InputEventMouseButton:
		if input_event.button_index == MOUSE_BUTTON_WHEEL_UP:
			zoom -= ZOOM_SPEED
		if input_event.button_index == MOUSE_BUTTON_WHEEL_DOWN:
			zoom += ZOOM_SPEED
		zoom = clampf(zoom, 1.5, 4)

	if input_event is InputEventMouseMotion and input_event.button_mask & MAIN_BUTTONS:
		# Use `screen_relative` to make mouse sensitivity independent of viewport resolution.
		var relative_motion: Vector2 = input_event.screen_relative
		rot_y -= relative_motion.x * ROT_SPEED
		rot_x -= relative_motion.y * ROT_SPEED
		rot_x = clampf(rot_x, deg_to_rad(-90), 0)
		camera_holder.transform.basis = Basis.from_euler(Vector3(0, rot_y, 0))
		rotation_x.transform.basis = Basis.from_euler(Vector3(rot_x, 0, 0))


func _process(delta: float) -> void:
	var current_tester: Node3D = testers.get_child(tester_index)
	# This code assumes CameraHolder's X and Y coordinates are already correct.
	var current_position := camera_holder.global_transform.origin.z
	var target_position := current_tester.global_transform.origin.z
	camera_holder.global_transform.origin.z = lerpf(current_position, target_position, 3 * delta)
	camera.position.z = lerpf(camera.position.z, zoom, 10 * delta)


func _on_previous_pressed() -> void:
	tester_index = max(0, tester_index - 1)
	update_gui()


func _on_next_pressed() -> void:
	tester_index = min(tester_index + 1, testers.get_child_count() - 1)
	update_gui()


func update_gui() -> void:
	$TestName.text = str(testers.get_child(tester_index).name).capitalize()
	$Previous.disabled = tester_index == 0
	$Next.disabled = tester_index == testers.get_child_count() - 1

# This script creates the ImageTexture and assigns it to an existing material at runtime.
# By not having `@tool`, this avoids saving the raw image data in the scene file,
# which would make it much larger.
extends MeshInstance3D


const TEXTURE_SIZE = Vector2i(512, 512)
const GRID_SIZE = 32
const GRID_THICKNESS = 4


func _ready() -> void:
	var image := Image.create(TEXTURE_SIZE.x, TEXTURE_SIZE.y, false, Image.FORMAT_RGB8)
	# Use 1-dimensional loop as it's faster than a nested loop.
	for i in TEXTURE_SIZE.x * TEXTURE_SIZE.y:
		var x := i % TEXTURE_SIZE.y
		var y := i / TEXTURE_SIZE.y
		var color := Color()

		# Draw a grid with more contrasted points where X and Y lines meet.
		# Center the grid's lines so that lines are visible on all the texture's edges.
		if (x + GRID_THICKNESS / 2) % GRID_SIZE < GRID_THICKNESS and (y + GRID_THICKNESS / 2) % GRID_SIZE < GRID_THICKNESS:
			color.g = 0.8
		elif (x + GRID_THICKNESS / 2) % GRID_SIZE < GRID_THICKNESS or (y + GRID_THICKNESS / 2) % GRID_SIZE < GRID_THICKNESS:
			color.g = 0.25

		# Add some random noise for detail.
		color += Color(randf(), randf(), randf()) * 0.1

		image.set_pixel(x, y, color)

	image.generate_mipmaps()
	var image_texture := ImageTexture.create_from_image(image)
	get_surface_override_material(0).albedo_texture = image_texture

	image.bump_map_to_normal_map(5.0)
	image.generate_mipmaps()
	var image_texture_normal := ImageTexture.create_from_image(image)
	get_surface_override_material(0).normal_texture = image_texture_normal

extends Node3D


const MOUSE_SENSITIVITY = 0.01
const INITIAL_VELOCITY_STRENGTH = 0.5

# Margin to add to the automatically computed shadow maximum distance.
# This value was empirically chosen to cover the whole scene when zoomed
# all the way in.
const DIRECTIONAL_SHADOW_MAX_DISTANCE_MARGIN = 9.0

@onready var camera_pivot: Node3D = $CameraPivot
@onready var camera: Camera3D = $CameraPivot/Camera3D
@onready var directional_light: DirectionalLight3D = $DirectionalLight3D


func _unhandled_input(input_event: InputEvent) -> void:
	if input_event.is_action_pressed(&"reset_simulation"):
		get_tree().reload_current_scene()

	if input_event.is_action_pressed(&"place_ragdoll"):
		var origin := camera.global_position
		var target := camera.project_position(get_viewport().get_mouse_position(), 100)

		var query := PhysicsRayQueryParameters3D.create(origin, target)
		var result := camera.get_world_3d().direct_space_state.intersect_ray(query)

		if not result.is_empty():
			var ragdoll := preload("res://characters/mannequiny_ragdoll.tscn").instantiate()
			ragdoll.position = result["position"] + Vector3(0.0, 0.5, 0.0)
			# Make newly spawned ragdolls face the camera.
			ragdoll.rotation.y = camera_pivot.rotation.y
			# Give some initial velocity in a random horizontal direction.
			ragdoll.initial_velocity = Vector3.FORWARD.rotated(Vector3.UP, randf_range(0, TAU)) * INITIAL_VELOCITY_STRENGTH
			add_child(ragdoll)

	if input_event.is_action_pressed(&"slow_motion"):
		Engine.time_scale = 0.25
		# Don't set pitch scale too low as it sounds strange.
		# `0.5` is the square root of `0.25` and gives a good result here.
		AudioServer.playback_speed_scale = 0.5

	if input_event.is_action_released(&"slow_motion"):
		Engine.time_scale = 1.0
		AudioServer.playback_speed_scale = 1.0

	# Pan the camera with right mouse button.
	if input_event is InputEventMouseMotion:
		var mouse_motion := input_event as InputEventMouseMotion
		if mouse_motion.button_mask & MOUSE_BUTTON_RIGHT:
			camera_pivot.global_rotation.x = clampf(camera_pivot.global_rotation.x - input_event.screen_relative.y * MOUSE_SENSITIVITY, -TAU * 0.249, TAU * 0.021)
			camera_pivot.global_rotation.y -= input_event.screen_relative.x * MOUSE_SENSITIVITY

	# Zoom with mouse wheel.
	# This also adjusts shadow maximum distance to always cover the scene regardless of zoom level.
	if input_event is InputEventMouseButton:
		var mouse_button := input_event as InputEventMouseButton
		if mouse_button.button_index == MOUSE_BUTTON_WHEEL_UP:
			camera.translate_object_local(Vector3.FORWARD * 0.5)
			directional_light.directional_shadow_max_distance = camera.position.length() + DIRECTIONAL_SHADOW_MAX_DISTANCE_MARGIN
		elif mouse_button.button_index == MOUSE_BUTTON_WHEEL_DOWN:
			camera.translate_object_local(Vector3.BACK * 0.5)
			directional_light.directional_shadow_max_distance = camera.position.length() + DIRECTIONAL_SHADOW_MAX_DISTANCE_MARGIN

extends Node3D

const IMPACT_SOUND_SPEED_SMALL = 0.3
const IMPACT_SOUND_SPEED_BIG = 1.0

## The velocity to apply on the first physics frame.
@export var initial_velocity: Vector3

var has_applied_initial_velocity: bool = false
# Used to play an impact sound on sudden velocity changes.
# We use the pelvis bone as it's close to the center of mass of the character model.
# For more detailed impact sounds, you could place multiple AudioStreamPlayer nodes as a child
# of each limb.
var previous_pelvis_speed: float = 0.0

@onready var pelvis: PhysicalBone3D = $"root/root_001/Skeleton3D/PhysicalBoneSimulator3D/Physical Bone pelvis"


func _ready() -> void:
	$root/root_001/Skeleton3D/PhysicalBoneSimulator3D.physical_bones_start_simulation()
	if not initial_velocity.is_zero_approx():
		for physical_bone in $root/root_001/Skeleton3D/PhysicalBoneSimulator3D.get_children():
			# Give the ragdoll an initial motion by applying velocity on all its bones upon being spawned.
			physical_bone.apply_central_impulse(initial_velocity)


func _physics_process(_delta: float) -> void:
	var pelvis_speed: float = pelvis.linear_velocity.length()
	# Ensure the speed used to determine the threshold doesn't change with time scale.
	var impact_speed := (previous_pelvis_speed - pelvis_speed) / Engine.time_scale
	if impact_speed > IMPACT_SOUND_SPEED_BIG:
		$ImpactSoundBig.play()
	elif impact_speed > IMPACT_SOUND_SPEED_SMALL:
		$ImpactSoundSmall.play()

	previous_pelvis_speed = pelvis_speed

extends RigidBody3D

@onready var shape_cast: ShapeCast3D = $ShapeCast3D
@onready var camera: Camera3D = $Target/Camera3D
@onready var start_position := position

func _physics_process(delta: float) -> void:
	if Input.is_action_just_pressed(&"exit"):
		get_tree().quit()
	if Input.is_action_just_pressed(&"reset_position") or global_position.y < -6.0:
		# Pressed the reset key or fell off the ground.
		position = start_position
		linear_velocity = Vector3.ZERO
		# We teleported the player on the lines above. Reset interpolation
		# to prevent it from interpolating from the old player position
		# to the new position.
		reset_physics_interpolation()

	var dir := Vector3()
	dir.x = Input.get_axis(&"move_left", &"move_right")
	dir.z = Input.get_axis(&"move_forward", &"move_back")

	# Get the camera's transform basis, but remove the X rotation such
	# that the Y axis is up and Z is horizontal.
	var cam_basis := camera.global_transform.basis
	cam_basis = cam_basis.rotated(cam_basis.x, -cam_basis.get_euler().x)
	dir = cam_basis * dir

	# Air movement.
	apply_central_impulse(dir.normalized() * 5.0 * delta)

	if on_ground():
		# Ground movement (higher acceleration).
		apply_central_impulse(dir.normalized() * 10.0 * delta)

		# Jumping code.
		# It's acceptable to set `linear_velocity` here as it's only set once, rather than continuously.
		# Vertical speed is set (rather than added) to prevent jumping higher than intended
		# if the ShapeCast3D collides for multiple frames.
		if Input.is_action_pressed(&"jump"):
			linear_velocity.y = 7


# Test if there is a body below the player.
func on_ground() -> bool:
	return shape_cast.is_colliding()


func _on_tcube_body_entered(body: Node) -> void:
	if body == self:
		$WinText.visible = true

@tool
extends Node3D


func _ready() -> void:
	# Create spheres to represent various levels of material roughness and metallic.
	for roughness in range(11):
		for metallic in range(11):
			var sphere := MeshInstance3D.new()
			sphere.mesh = SphereMesh.new()
			# Center the spheres around the node origin.
			sphere.position = Vector3(roughness, 0, metallic) - Vector3(5, 0, 5)

			var material := StandardMaterial3D.new()
			material.albedo_color = Color(0.5, 0.5, 0.5)
			material.roughness = roughness * 0.1
			material.metallic = metallic * 0.1
			sphere.material_override = material

			add_child(sphere)

extends WorldEnvironment


const ROT_SPEED: float = 0.003
const ZOOM_SPEED: float = 0.125
const MAIN_BUTTONS: int = MOUSE_BUTTON_MASK_LEFT | MOUSE_BUTTON_MASK_RIGHT | MOUSE_BUTTON_MASK_MIDDLE

## The maximum number of additional cloths and boxes that can be spawned at a given time
## (for performance reasons).
const MAX_ADDITIONAL_ITEMS: int = 10

const Cloth: PackedScene = preload("res://cloth.tscn")
const RigidBoxLight: PackedScene = preload("res://rigid_box_light.tscn")
const RigidBoxHeavy: PackedScene = preload("res://rigid_box_heavy.tscn")
const Box: PackedScene = preload("res://box.tscn")
const Sphere: PackedScene = preload("res://sphere.tscn")

var tester_index: int = 0
var rot_x: float = deg_to_rad(-22.5)  # This must be kept in sync with RotationX.
var rot_y: float = deg_to_rad(90.0)  # This must be kept in sync with CameraHolder.
var zoom: float = 1.5
var base_height := int(ProjectSettings.get_setting("display/window/size/viewport_height"))

var additional_items: Array[Node3D] = []

@onready var testers: Node3D = $Testers
@onready var camera_holder: Node3D = $CameraHolder  # Has a position and rotates around Y.
@onready var rotation_x: Node3D = $CameraHolder/RotationX
@onready var camera: Camera3D = $CameraHolder/RotationX/Camera3D

@onready var nodes_to_reset: Array[SoftBody3D] = [
	$Testers/ClothPhysics/Cloth,
	$Testers/SoftBoxes/Box,
	$Testers/SoftBoxes/Box2,
	$Testers/SoftSpheres/Sphere,
	$Testers/SoftSpheres/Sphere2,
	$Testers/CentralImpulseTimer/Cloth,
	$Testers/PerPointImpulseTimer/Cloth,
	$Testers/CentralForceWind/Cloth,
	$Testers/PinnedPoints/PinnedCloth,
]

@onready var nodes_to_reset_types: Array[PackedScene] = [
	Cloth,
	Box,
	Box,
	Sphere,
	Sphere,
	Cloth,
	Cloth,
	Cloth,
	Cloth,
]

@onready var nodes_to_reset_global_positions: PackedVector3Array


func _ready() -> void:
	for node: Node3D in nodes_to_reset:
		nodes_to_reset_global_positions.push_back(node.global_position)

	camera_holder.transform.basis = Basis.from_euler(Vector3(0, rot_y, 0))
	rotation_x.transform.basis = Basis.from_euler(Vector3(rot_x, 0, 0))
	update_gui()


func _unhandled_input(input_event: InputEvent) -> void:
	if input_event.is_action_pressed(&"ui_left"):
		_on_previous_pressed()
	if input_event.is_action_pressed(&"ui_right"):
		_on_next_pressed()

	if input_event.is_action_pressed(&"reset_physics_simulation"):
		# Remove all additional (player-spawned) items.
		for additional_item in additional_items:
			additional_item.queue_free()

		additional_items.clear()

		# Reset everything to its base state by removing existing nodes and reinstancing new scenes to replace them.
		for idx in nodes_to_reset.size():
			var previous_name: String = nodes_to_reset[idx].name
			var previous_parent: Node = nodes_to_reset[idx].get_parent()
			nodes_to_reset[idx].queue_free()
			nodes_to_reset[idx] = nodes_to_reset_types[idx].instantiate()
			previous_parent.add_child(nodes_to_reset[idx])
			nodes_to_reset[idx].name = previous_name
			nodes_to_reset[idx].global_position = nodes_to_reset_global_positions[idx]
			if "PinnedCloth" in nodes_to_reset[idx].name:
				# Pin the four corners of the cloth.
				# These vertex IDs are valid with the PlaneMesh subdivision level set to 63 on both axes.
				for point: int in [0, 64, 4160, 4224]:
					nodes_to_reset[idx].set_point_pinned(point, true)

	if (
			input_event.is_action_pressed(&"place_cloth") or
			input_event.is_action_pressed(&"place_light_box") or
			input_event.is_action_pressed(&"place_heavy_box")
	):
		# Place a new item and track it in an additional items array, so we can limit
		# the number of player-spawned items present in the scene at a given time.
		var origin: Vector3 = camera.global_position
		var target: Vector3 = camera.project_position(get_viewport().get_mouse_position(), 100)

		var query := PhysicsRayQueryParameters3D.create(origin, target)
		# Ignore layer 2 which contains invisible walls.
		query.collision_mask = 1
		var result := camera.get_world_3d().direct_space_state.intersect_ray(query)

		if not result.is_empty():
			if additional_items.size() >= MAX_ADDITIONAL_ITEMS:
				additional_items.pop_front().queue_free()

			var node: Node3D
			if input_event.is_action_pressed(&"place_cloth"):
				node = Cloth.instantiate()
				# Make user-placed cloth translucent to distinguish from the scene's own cloths.
				node.transparency = 0.35
			elif input_event.is_action_pressed(&"place_light_box"):
				node = RigidBoxLight.instantiate()
			else:
				node = RigidBoxHeavy.instantiate()

			node.position = result["position"] + Vector3(0, 0.5, 0)
			add_child(node)
			additional_items.push_back(node)

	if input_event is InputEventMouseButton:
		if input_event.button_index == MOUSE_BUTTON_WHEEL_UP:
			zoom -= ZOOM_SPEED
		if input_event.button_index == MOUSE_BUTTON_WHEEL_DOWN:
			zoom += ZOOM_SPEED
		zoom = clampf(zoom, 1.5, 4)

	if input_event is InputEventMouseMotion and input_event.button_mask & MAIN_BUTTONS:
		# Compensate motion speed to be resolution-independent (based on the window height).
		var relative_motion: Vector2 = input_event.relative * DisplayServer.window_get_size().y / base_height
		rot_y -= relative_motion.x * ROT_SPEED
		rot_x -= relative_motion.y * ROT_SPEED
		rot_x = clampf(rot_x, deg_to_rad(-90), 0)
		camera_holder.transform.basis = Basis.from_euler(Vector3(0, rot_y, 0))
		rotation_x.transform.basis = Basis.from_euler(Vector3(rot_x, 0, 0))


func _process(delta: float) -> void:
	var current_tester: Node3D = testers.get_child(tester_index)
	# This code assumes CameraHolder's X and Y coordinates are already correct.
	var current_position_z: float = camera_holder.global_transform.origin.z
	var target_position_z: float = current_tester.global_transform.origin.z
	camera_holder.global_transform.origin.z = lerpf(current_position_z, target_position_z, 3 * delta)
	camera.position.z = lerpf(camera.position.z, zoom, 10 * delta)


func _physics_process(delta: float) -> void:
	# Strong sideways wind force, which pushes the cloth while airborne and
	# makes it wave around once it has landed.
	const WIND_FORCE: float = 2_450_000.0
	for node in $Testers/CentralForceWind.get_children():
		if node is SoftBody3D:
			node.apply_central_force(Vector3(1.0, 0.0, 0.0) * WIND_FORCE * delta)

	# Use a loop to determine the right node to follow
	# (we need to do this as the node will have a different name after resetting).
	for cloth in $Testers/PerPointImpulseTimer.get_children():
		if cloth is SoftBody3D:
			for node in $Testers/PerPointImpulseTimer/PointTrackers.get_children():
				# Make the point trackers follow specific points stored in node metadata.
				# This can be used to make any node type (such as particles, a mesh, or even a rigid body)
				# follow a point. It's also possible to average the position of several points
				# to make an object follow an edge or a face in a best-effort manner.
				#
				# We slightly shift the tracker upwards to account for the cloth's thickness
				# (specified in the cloth material's Grow property).
				node.global_position = cloth.get_point_transform(node.get_meta(&"point")) + Vector3(0.0, 0.01, 0.0)


func _on_previous_pressed() -> void:
	tester_index = max(0, tester_index - 1)
	update_gui()


func _on_next_pressed() -> void:
	tester_index = min(tester_index + 1, testers.get_child_count() - 1)
	update_gui()


func update_gui() -> void:
	$TestName.text = str(testers.get_child(tester_index).name).capitalize()
	$Previous.disabled = tester_index == 0
	$Next.disabled = tester_index == testers.get_child_count() - 1


func _on_central_impulse_timer_timeout() -> void:
	# When using `apply_central_impulse()` instead of `apply_impulse()`,
	# we have to use a much larger value to get significant movement as the impulse is distributed
	# across all points.
	const INTENSITY: float = 8000.0

	for node in $Testers/CentralImpulseTimer.get_children():
		if node is SoftBody3D:
			var random_unit_vector := Vector3(randf_range(-1.0, 1.0), randf_range(-0.0, 1.0), randf_range(-1.0, 1.0)).normalized()
			node.apply_central_impulse(random_unit_vector * INTENSITY)


func _on_per_point_impulse_timer_timeout() -> void:
	const INTENSITY: float = 600.0

	for node in $Testers/PerPointImpulseTimer.get_children():
		if node is SoftBody3D:
			# Apply impulse on the four corners of the cloth.
			# These vertex IDs are valid with the PlaneMesh subdivision level set to 63 on both axes.
			for point: int in [0, 64, 4160, 4224]:
				var random_unit_vector := Vector3(randf_range(-1.0, 1.0), randf_range(-0.0, 1.0), randf_range(-1.0, 1.0)).normalized()
				node.apply_impulse(point, random_unit_vector * INTENSITY)

