extends CharacterBody3D

const EYE_HEIGHT_STAND = 1.6
const EYE_HEIGHT_CROUCH = 1.4

const MOVEMENT_SPEED_GROUND = 70.0
const MOVEMENT_SPEED_AIR = 13.0
const MOVEMENT_SPEED_CROUCH_MODIFIER = 0.5
const MOVEMENT_SPEED_SPRINT_MODIFIER = 1.375
const MOVEMENT_FRICTION_GROUND = 12.5
const MOVEMENT_FRICTION_AIR = 2.25
const MOVEMENT_JUMP_VELOCITY = 9.0

var _mouse_motion := Vector2()
var _selected_block := 6

@onready var head: Node3D = $Head
@onready var camera: Camera3D = $Head/Camera3D
@onready var raycast: RayCast3D = $Head/RayCast3D
@onready var camera_attributes: CameraAttributes = $Head/Camera3D.attributes
@onready var selected_block_texture: TextureRect = $SelectedBlock
@onready var voxel_world: VoxelWorld = $"../VoxelWorld"
@onready var crosshair: CenterContainer = $"../PauseMenu/Crosshair"
@onready var aim_preview: MeshInstance3D = $AimPreview
@onready var neutral_fov: float = camera.fov


func _ready() -> void:
	Input.mouse_mode = Input.MOUSE_MODE_CAPTURED


func _process(_delta: float) -> void:
	# Mouse movement.
	_mouse_motion.y = clampf(_mouse_motion.y, -1560, 1560)
	transform.basis = Basis.from_euler(Vector3(0, _mouse_motion.x * -0.001, 0))
	head.transform.basis = Basis.from_euler(Vector3(_mouse_motion.y * -0.001, 0, 0))

	# Block selection.
	var ray_position := raycast.get_collision_point()
	var ray_normal := raycast.get_collision_normal()
	if Input.is_action_just_pressed(&"pick_block"):
		# Block picking.
		var block_global_position: Vector3 = (ray_position - ray_normal / 2).floor()
		var block_sub_position: Vector3 = block_global_position.posmod(16)
		var chunk_position: Vector3 = (block_global_position - block_sub_position) / 16
		_selected_block = voxel_world.get_block_in_chunk(chunk_position, block_sub_position)
	else:
		# Block prev/next keys.
		if Input.is_action_just_pressed(&"prev_block"):
			_selected_block -= 1
		if Input.is_action_just_pressed(&"next_block"):
			_selected_block += 1
		_selected_block = wrapi(_selected_block, 1, 30)
	# Set the appropriate texture.
	var uv := Chunk.calculate_block_uvs(_selected_block)
	selected_block_texture.texture.region = Rect2(uv[0] * 512, Vector2.ONE * 64)

	# Block breaking/placing.
	if crosshair.visible and raycast.is_colliding():
		aim_preview.visible = true
		var ray_current_block_position := Vector3i((ray_position - ray_normal / 2).floor())
		aim_preview.global_position = Vector3(ray_current_block_position) + Vector3(0.5, 0.5, 0.5)
		var breaking := Input.is_action_just_pressed(&"break")
		var placing := Input.is_action_just_pressed(&"place")
		# Either both buttons were pressed or neither is, so stop.
		if breaking == placing:
			return

		if breaking:
			var block_global_position := ray_current_block_position
			voxel_world.set_block_global_position(block_global_position, 0)
		elif placing:
			# Calculate the position of the block to be placed.
			var block_global_position := Vector3i((ray_position + ray_normal / 2).floor())
			voxel_world.set_block_global_position(block_global_position, _selected_block)
	else:
		aim_preview.visible = false


func _physics_process(delta: float) -> void:
	camera_attributes.dof_blur_far_enabled = Settings.fog_enabled
	camera_attributes.dof_blur_far_distance = Settings.fog_distance * 1.5
	camera_attributes.dof_blur_far_transition = Settings.fog_distance * 0.125
	# Crouching.
	var crouching: bool = Input.is_action_pressed(&"crouch")
	var sprinting: bool = Input.is_action_pressed(&"move_sprint")
	head.transform.origin.y = lerpf(head.transform.origin.y, EYE_HEIGHT_CROUCH if crouching else EYE_HEIGHT_STAND, 1.0 - exp(-delta * 16.0))

	# Keyboard movement.
	var movement_vec2: Vector2 = Input.get_vector(&"move_left", &"move_right", &"move_forward", &"move_back")
	var movement: Vector3 = transform.basis * (Vector3(movement_vec2.x, 0, movement_vec2.y))

	if is_on_floor():
		movement *= MOVEMENT_SPEED_GROUND
	else:
		movement *= MOVEMENT_SPEED_AIR

	if crouching:
		movement *= MOVEMENT_SPEED_CROUCH_MODIFIER
		sprinting = false
	var target_fov: float = neutral_fov
	if sprinting:
		movement *= MOVEMENT_SPEED_SPRINT_MODIFIER
		target_fov = neutral_fov * 1.25
	camera.fov = lerpf(camera.fov, target_fov, 1.0 - exp(-delta * 10.0))

	# Gravity.
	if not is_on_floor():
		var factor: float = 3.0 - clampf(velocity.y / -MOVEMENT_JUMP_VELOCITY, 0.0, 2.0)
		velocity += get_gravity() * (delta * factor)

	velocity += Vector3(movement.x, 0, movement.z) * delta
	# Apply horizontal friction.
	var friction_delta := exp(-(MOVEMENT_FRICTION_GROUND if is_on_floor() else MOVEMENT_FRICTION_AIR) * delta)
	velocity = Vector3(velocity.x * friction_delta, velocity.y, velocity.z * friction_delta)
	move_and_slide()

	# Jumping, applied next frame.
	if is_on_floor() and Input.is_action_pressed(&"jump"):
		velocity.y = MOVEMENT_JUMP_VELOCITY


func _input(input_event: InputEvent) -> void:
	if input_event is InputEventMouseMotion:
		if Input.get_mouse_mode() == Input.MOUSE_MODE_CAPTURED:
			_mouse_motion += input_event.screen_relative


func chunk_pos() -> Vector3i:
	return Vector3i((transform.origin / Chunk.CHUNK_SIZE).floor())

class_name Chunk
extends StaticBody3D
# These chunks are instanced and given data by VoxelWorld.
# After that, chunks finish setting themselves up in the _ready() function.
# If a chunk is changed, its "regenerate" method is called.

const CHUNK_SIZE := 16 # Keep in sync with TerrainGenerator.
const TEXTURE_SHEET_WIDTH := 8
const CHUNK_LAST_INDEX := CHUNK_SIZE - 1
const TEXTURE_TILE_SIZE := 1.0 / TEXTURE_SHEET_WIDTH
const CHUNK_EXTENTS := Vector3.ONE / 2.0
const DIRECTIONS: Array[Vector3i] = [Vector3i.LEFT, Vector3i.RIGHT, Vector3i.DOWN, Vector3i.UP, Vector3i.FORWARD, Vector3i.BACK]

var data: Dictionary[Vector3i, int] = {}
var chunk_position := Vector3i()
var is_initial_mesh_generated: bool = false
var mesh_task_id := 0

static var box_shape: BoxShape3D = null

@onready var voxel_world := get_parent() as VoxelWorld


func _init(pos: Vector3i) -> void:
	chunk_position = pos
	transform.origin = Vector3(chunk_position * CHUNK_SIZE)
	name = str(chunk_position)
	if Settings.world_type == 0:
		data = TerrainGenerator.random_blocks()
	else:
		data = TerrainGenerator.flat(chunk_position)

	# We can only add colliders in the main thread due to physics limitations.
	_generate_chunk_collider()


func _notification(what: int) -> void:
	if what == NOTIFICATION_PREDELETE:
		if mesh_task_id >= 1:
			WorkerThreadPool.wait_for_task_completion(mesh_task_id)
			mesh_task_id = 0


func try_initial_generate_mesh(all_chunks: Dictionary[Vector3i, Chunk]) -> void:
	# We can use a thread for mesh generation.
	for dir in DIRECTIONS:
		if not all_chunks.has(chunk_position + dir):
			return
	is_initial_mesh_generated = true
	mesh_task_id = WorkerThreadPool.add_task(_generate_chunk_mesh, true)


func regenerate() -> void:
	# Making shape changes to bodies with many/complex shapes, while the body is in the scene tree,
	# can be expensive when using Jolt Physics, so we temporarily remove it from the scene tree.
	voxel_world.remove_child(self)

	# Clear out all old nodes first.
	for c in get_children():
		remove_child(c)
		c.queue_free()

	# Then generate new ones.
	_generate_chunk_collider()
	_generate_chunk_mesh()

	voxel_world.add_child(self)


func _generate_chunk_collider() -> void:
	if data.is_empty():
		return

	# For each block, generate a collider.
	for block_position: Vector3i in data.keys():
		var block_id: int = data[block_position]
		if block_id != 27 and block_id != 28:
			_create_block_collider(block_position)


func _generate_chunk_mesh() -> void:
	if data.is_empty():
		return

	var surface_tool := SurfaceTool.new()
	surface_tool.begin(Mesh.PRIMITIVE_TRIANGLES)

	# For each block, add data to the SurfaceTool and generate a collider.
	for block_position: Vector3i in data.keys():
		var block_id: int = data[block_position]
		_draw_block_mesh(surface_tool, block_position, block_id)

	# Create the chunk's mesh from the SurfaceTool data.
	surface_tool.generate_tangents()
	surface_tool.index()
	var array_mesh := surface_tool.commit()
	var mi := MeshInstance3D.new()
	mi.mesh = array_mesh
	mi.material_override = preload("res://world/textures/material.tres")
	add_child.call_deferred(mi)


func _draw_block_mesh(surface_tool: SurfaceTool, block_sub_position: Vector3i, block_id: int) -> void:
	var verts := Chunk.calculate_block_verts(block_sub_position)
	var uvs := Chunk.calculate_block_uvs(block_id)
	var top_uvs := uvs
	var bottom_uvs := uvs

	# Bush blocks get drawn in their own special way.
	if block_id == 27 or block_id == 28:
		_draw_block_face(surface_tool, [verts[2], verts[0], verts[7], verts[5]], uvs, Vector3(-1, 0, 1).normalized())
		_draw_block_face(surface_tool, [verts[7], verts[5], verts[2], verts[0]], uvs, Vector3(1, 0, -1).normalized())
		_draw_block_face(surface_tool, [verts[3], verts[1], verts[6], verts[4]], uvs, Vector3(1, 0, 1).normalized())
		_draw_block_face(surface_tool, [verts[6], verts[4], verts[3], verts[1]], uvs, Vector3(-1, 0, -1).normalized())
		return

	# Allow some blocks to have different top/bottom textures.
	if block_id == 3: # Grass.
		top_uvs = Chunk.calculate_block_uvs(0)
		bottom_uvs = Chunk.calculate_block_uvs(2)
	elif block_id == 5: # Furnace.
		top_uvs = Chunk.calculate_block_uvs(31)
		bottom_uvs = top_uvs
	elif block_id == 12: # Log.
		top_uvs = Chunk.calculate_block_uvs(30)
		bottom_uvs = top_uvs
	elif block_id == 19: # Bookshelf.
		top_uvs = Chunk.calculate_block_uvs(4)
		bottom_uvs = top_uvs

	# Main rendering code for normal blocks.
	#var other_block_position := block_sub_position
	var other_block_id := 0
	if block_sub_position.x == 0:
		var other_sub_pos: Vector3i = Vector3i(15, block_sub_position.y, block_sub_position.z)
		other_block_id = voxel_world.get_block_in_chunk(chunk_position + Vector3i.LEFT, other_sub_pos)
	else:
		var other_block_sub_pos: Vector3i = block_sub_position + Vector3i.LEFT
		if data.has(other_block_sub_pos):
			other_block_id = data[other_block_sub_pos]
	if block_id != other_block_id and Chunk.is_block_transparent(other_block_id):
		_draw_block_face(surface_tool, [verts[2], verts[0], verts[3], verts[1]], uvs, Vector3.LEFT)

	other_block_id = 0
	if block_sub_position.x == CHUNK_SIZE - 1:
		var other_sub_pos: Vector3i = Vector3i(0, block_sub_position.y, block_sub_position.z)
		other_block_id = voxel_world.get_block_in_chunk(chunk_position + Vector3i.RIGHT, other_sub_pos)
	else:
		var other_block_sub_pos: Vector3i = block_sub_position + Vector3i.RIGHT
		if data.has(other_block_sub_pos):
			other_block_id = data[other_block_sub_pos]
	if block_id != other_block_id and Chunk.is_block_transparent(other_block_id):
		_draw_block_face(surface_tool, [verts[7], verts[5], verts[6], verts[4]], uvs, Vector3.RIGHT)

	other_block_id = 0
	if block_sub_position.z == 0:
		var other_sub_pos: Vector3i = Vector3i(block_sub_position.x, block_sub_position.y, CHUNK_SIZE - 1)
		other_block_id = voxel_world.get_block_in_chunk(chunk_position + Vector3i.FORWARD, other_sub_pos)
	else:
		var other_block_sub_pos: Vector3i = block_sub_position + Vector3i.FORWARD
		if data.has(other_block_sub_pos):
			other_block_id = data[other_block_sub_pos]
	if block_id != other_block_id and Chunk.is_block_transparent(other_block_id):
		_draw_block_face(surface_tool, [verts[6], verts[4], verts[2], verts[0]], uvs, Vector3.FORWARD)

	other_block_id = 0
	if block_sub_position.z == CHUNK_SIZE - 1:
		var other_sub_pos: Vector3i = Vector3i(block_sub_position.x, block_sub_position.y, 0)
		other_block_id = voxel_world.get_block_in_chunk(chunk_position + Vector3i.BACK, other_sub_pos)
	else:
		var other_block_sub_pos: Vector3i = block_sub_position + Vector3i.BACK
		if data.has(other_block_sub_pos):
			other_block_id = data[other_block_sub_pos]
	if block_id != other_block_id and Chunk.is_block_transparent(other_block_id):
		_draw_block_face(surface_tool, [verts[3], verts[1], verts[7], verts[5]], uvs, Vector3.BACK)

	other_block_id = 0
	if block_sub_position.y == 0:
		var other_sub_pos: Vector3i = Vector3i(block_sub_position.x, CHUNK_SIZE - 1, block_sub_position.z)
		other_block_id = voxel_world.get_block_in_chunk(chunk_position + Vector3i.DOWN, other_sub_pos)
	else:
		var other_block_sub_pos: Vector3i = block_sub_position + Vector3i.DOWN
		if data.has(other_block_sub_pos):
			other_block_id = data[other_block_sub_pos]
	if block_id != other_block_id and Chunk.is_block_transparent(other_block_id):
		_draw_block_face(surface_tool, [verts[4], verts[5], verts[0], verts[1]], bottom_uvs, Vector3.DOWN)

	other_block_id = 0
	if block_sub_position.y == CHUNK_SIZE - 1:
		var other_sub_pos: Vector3i = Vector3i(block_sub_position.x, 0, block_sub_position.z)
		other_block_id = voxel_world.get_block_in_chunk(chunk_position + Vector3i.UP, other_sub_pos)
	else:
		var other_block_sub_pos: Vector3i = block_sub_position + Vector3i.UP
		if data.has(other_block_sub_pos):
			other_block_id = data[other_block_sub_pos]
	if block_id != other_block_id and Chunk.is_block_transparent(other_block_id):
		_draw_block_face(surface_tool, [verts[2], verts[3], verts[6], verts[7]], top_uvs, Vector3.UP)


func _draw_block_face(surface_tool: SurfaceTool, verts: Array[Vector3], uvs: Array[Vector2], normal: Vector3) -> void:
	surface_tool.set_normal(normal)
	surface_tool.set_uv(uvs[1]); surface_tool.add_vertex(verts[1])
	surface_tool.set_uv(uvs[2]); surface_tool.add_vertex(verts[2])
	surface_tool.set_uv(uvs[3]); surface_tool.add_vertex(verts[3])

	surface_tool.set_uv(uvs[2]); surface_tool.add_vertex(verts[2])
	surface_tool.set_uv(uvs[1]); surface_tool.add_vertex(verts[1])
	surface_tool.set_uv(uvs[0]); surface_tool.add_vertex(verts[0])


func _create_block_collider(block_sub_position: Vector3) -> void:
	if not box_shape:
		box_shape = BoxShape3D.new()
		box_shape.extents = CHUNK_EXTENTS

	var collider := CollisionShape3D.new()
	collider.shape = box_shape
	collider.transform.origin = block_sub_position + CHUNK_EXTENTS
	add_child(collider)


static func calculate_block_uvs(block_id: int) -> Array[Vector2]:
	# This method only supports square texture sheets.
	@warning_ignore("integer_division")
	var row := block_id / TEXTURE_SHEET_WIDTH
	var col := block_id % TEXTURE_SHEET_WIDTH

	return [
			# Godot 4 has a weird bug where there are seams at the edge
			# of the textures. Adding a margin of 0.01 "fixes" it.
			TEXTURE_TILE_SIZE * Vector2(col + 0.01, row + 0.01),
			TEXTURE_TILE_SIZE * Vector2(col + 0.01, row + 0.99),
			TEXTURE_TILE_SIZE * Vector2(col + 0.99, row + 0.01),
			TEXTURE_TILE_SIZE * Vector2(col + 0.99, row + 0.99),
		]


static func calculate_block_verts(block_position: Vector3) -> Array[Vector3]:
	return [
			Vector3(block_position.x, block_position.y, block_position.z),
			Vector3(block_position.x, block_position.y, block_position.z + 1),
			Vector3(block_position.x, block_position.y + 1, block_position.z),
			Vector3(block_position.x, block_position.y + 1, block_position.z + 1),
			Vector3(block_position.x + 1, block_position.y, block_position.z),
			Vector3(block_position.x + 1, block_position.y, block_position.z + 1),
			Vector3(block_position.x + 1, block_position.y + 1, block_position.z),
			Vector3(block_position.x + 1, block_position.y + 1, block_position.z + 1),
		]


static func is_block_transparent(block_id: int) -> int:
	return block_id == 0 or (block_id > 25 and block_id < 30)

class_name TerrainGenerator
extends Resource

const RANDOM_BLOCK_PROBABILITY = 0.015

static func empty() -> Dictionary[Vector3i, int]:
	return {}


static func random_blocks() -> Dictionary[Vector3i, int]:
	var random_data: Dictionary[Vector3i, int] = {}
	for x in Chunk.CHUNK_SIZE:
		for y in Chunk.CHUNK_SIZE:
			for z in Chunk.CHUNK_SIZE:
				var vec := Vector3i(x, y, z)
				if randf() < RANDOM_BLOCK_PROBABILITY:
					random_data[vec] = randi() % 29 + 1

	return random_data


static func flat(chunk_position: Vector3i) -> Dictionary[Vector3i, int]:
	var data: Dictionary[Vector3i, int] = {}

	if chunk_position.y != -1:
		return data

	for x in Chunk.CHUNK_SIZE:
		for z in Chunk.CHUNK_SIZE:
			data[Vector3i(x, 2, z)] = 3  # Grass.
			data[Vector3i(x, 1, z)] = 2  # Dirt.
			data[Vector3i(x, 0, z)] = 2  # Dirt.
			data[Vector3i(x, -1, z)] = 9  # Bedrock (can't be destroyed due to its Y coordinate).

	return data


# Used to create the project icon.
static func origin_grass(chunk_position: Vector3i) -> Dictionary[Vector3i, int]:
	if chunk_position == Vector3i.ZERO:
		return { Vector3i.ZERO: 3 }

	return {}

class_name VoxelWorld
extends Node
# This file manages the creation and deletion of Chunks.

const CHUNK_MIDPOINT = Vector3(0.5, 0.5, 0.5) * Chunk.CHUNK_SIZE
const CHUNK_END_SIZE = Chunk.CHUNK_SIZE - 1
const DIRECTIONS: Array[Vector3i] = [Vector3i.LEFT, Vector3i.RIGHT, Vector3i.DOWN, Vector3i.UP, Vector3i.FORWARD, Vector3i.BACK]

var render_distance: int:
	set(value):
		render_distance = value
		_delete_distance = value + 2

var _delete_distance := 0
var effective_render_distance := 0
var _old_player_chunk := Vector3i()

var _generating: bool = true
var _deleting: bool = false

var _chunks: Dictionary[Vector3i, Chunk] = {}

@onready var player: CharacterBody3D = $"../Player"

func _process(_delta: float) -> void:
	render_distance = Settings.render_distance
	var player_chunk := Vector3i((player.transform.origin / Chunk.CHUNK_SIZE).round())

	if _deleting or player_chunk != _old_player_chunk:
		_delete_far_away_chunks(player_chunk)
		_generating = true

	if not _generating:
		return

	# Try to generate chunks ahead of time based on where the player is moving.
	@warning_ignore("integer_division")
	player_chunk.y += roundi(clampf(player.velocity.y, -render_distance / 4, render_distance / 4))

	# Check existing chunks within range. If it doesn't exist, create it.
	for x in range(player_chunk.x - effective_render_distance, player_chunk.x + effective_render_distance):
		for y in range(player_chunk.y - effective_render_distance, player_chunk.y + effective_render_distance):
			for z in range(player_chunk.z - effective_render_distance, player_chunk.z + effective_render_distance):
				var chunk_position := Vector3i(x, y, z)
				if Vector3(player_chunk).distance_to(Vector3(chunk_position)) > render_distance:
					continue

				if _chunks.has(chunk_position):
					continue

				var chunk := Chunk.new(chunk_position)
				_chunks[chunk_position] = chunk
				add_child(chunk)
				chunk.try_initial_generate_mesh(_chunks)
				for dir in DIRECTIONS:
					var neighbor: Chunk = _chunks.get(chunk_position + dir)
					if neighbor != null and not neighbor.is_initial_mesh_generated:
						neighbor.try_initial_generate_mesh(_chunks)
				# Generate at most one chunk per frame in terms of data/colliders.
				# Mesh generation is threaded so it's ok that the above may generate multiple meshes.
				return

	# If we didn't generate any chunks (and therefore didn't return), what next?
	if effective_render_distance < render_distance:
		# We can move on to the next stage by increasing the effective distance.
		effective_render_distance += 1
	else:
		# Effective render distance is maxed out, done generating.
		_generating = false


func get_block_in_chunk(chunk_position: Vector3i, block_sub_position: Vector3i) -> int:
	if _chunks.has(chunk_position):
		var chunk: Chunk = _chunks[chunk_position]
		if chunk.data.has(block_sub_position):
			return chunk.data[block_sub_position]
	return 0


func set_block_global_position(block_global_position: Vector3i, block_id: int) -> void:
	var chunk_position := Vector3i((Vector3(block_global_position) / Chunk.CHUNK_SIZE).floor())
	var chunk: Chunk = _chunks[chunk_position]
	var sub_position := Vector3i(Vector3(block_global_position).posmod(Chunk.CHUNK_SIZE))
	if block_id == 0:
		chunk.data.erase(sub_position)
	else:
		chunk.data[sub_position] = block_id
	chunk.regenerate()

	# We also might need to regenerate some neighboring chunks.
	if Chunk.is_block_transparent(block_id):
		if sub_position.x == 0:
			_chunks[chunk_position + Vector3i.LEFT].regenerate()
		elif sub_position.x == CHUNK_END_SIZE:
			_chunks[chunk_position + Vector3i.RIGHT].regenerate()
		if sub_position.z == 0:
			_chunks[chunk_position + Vector3i.FORWARD].regenerate()
		elif sub_position.z == CHUNK_END_SIZE:
			_chunks[chunk_position + Vector3i.BACK].regenerate()
		if sub_position.y == 0:
			_chunks[chunk_position + Vector3i.DOWN].regenerate()
		elif sub_position.y == CHUNK_END_SIZE:
			_chunks[chunk_position + Vector3i.UP].regenerate()


func clean_up() -> void:
	_chunks = {}
	set_process(false)

	for c in get_children():
		c.free()


func _delete_far_away_chunks(player_chunk: Vector3i) -> void:
	_old_player_chunk = player_chunk
	# If we need to delete chunks, give the new chunk system a chance to catch up.
	effective_render_distance = maxi(1, effective_render_distance - 1)

	var deleted_this_frame := 0
	# We should delete old chunks more aggressively if moving fast.
	# An easy way to calculate this is by using the effective render distance.
	# The specific values in this formula are arbitrary and from experimentation.
	var max_deletions := clampi(2 * (render_distance - effective_render_distance), 2, 8)
	# Also take the opportunity to delete far away chunks.
	for chunk_position_key: Vector3i in _chunks.keys():
		if Vector3(player_chunk).distance_to(Vector3(chunk_position_key)) > _delete_distance:
			_chunks[chunk_position_key].queue_free()
			_chunks.erase(chunk_position_key)
			deleted_this_frame += 1
			# Limit the amount of deletions per frame to avoid lag spikes.
			if deleted_this_frame > max_deletions:
				# Continue deleting next frame.
				_deleting = true
				return

	# We're done deleting.
	_deleting = false

extends Camera3D


const MOUSE_SENSITIVITY = 0.002
const MOVE_SPEED = 0.65

var rot := Vector3()
var velocity := Vector3()


func _ready() -> void:
	Input.mouse_mode = Input.MOUSE_MODE_CAPTURED


func _input(input_event: InputEvent) -> void:
	# Mouse look (only if the mouse is captured).
	if input_event is InputEventMouseMotion and Input.get_mouse_mode() == Input.MOUSE_MODE_CAPTURED:
		# Horizontal mouse look.
		rot.y -= input_event.screen_relative.x * MOUSE_SENSITIVITY
		# Vertical mouse look.
		rot.x = clamp(rot.x - input_event.screen_relative.y * MOUSE_SENSITIVITY, -1.57, 1.57)
		transform.basis = Basis.from_euler(rot)

	if input_event.is_action_pressed(&"toggle_mouse_capture"):
		if Input.get_mouse_mode() == Input.MOUSE_MODE_CAPTURED:
			Input.set_mouse_mode(Input.MOUSE_MODE_VISIBLE)
		else:
			Input.set_mouse_mode(Input.MOUSE_MODE_CAPTURED)


func _process(delta: float) -> void:
	var motion := Vector3(
			Input.get_axis(&"move_left", &"move_right"),
			0,
			Input.get_axis(&"move_forward", &"move_back")
		)

	# Normalize motion to prevent diagonal movement from being
	# `sqrt(2)` times faster than straight movement.
	motion = motion.normalized()

	velocity += MOVE_SPEED * delta * (transform.basis * motion)
	velocity *= 0.85
	position += velocity

